functions.account_email_request:
CREATE OR REPLACE FUNCTION public.account_email_request(p_actor uuid, p_target uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE target_email text;
BEGIN
 IF p_actor IS NULL OR (p_actor<>p_target AND (NOT private.account_enabled(p_actor) OR NOT public.has_role(p_actor,'admin'::public.app_role))) THEN RAISE EXCEPTION 'account:forbidden' USING ERRCODE='42501'; END IF;
 SELECT email INTO STRICT target_email FROM auth.users WHERE id=p_target;
 INSERT INTO private.email_verification_requests(user_id) VALUES(p_target) ON CONFLICT(user_id) DO UPDATE SET requested_at=clock_timestamp()
 WHERE private.email_verification_requests.requested_at<clock_timestamp()-interval '60 seconds';
 IF NOT FOUND THEN RAISE EXCEPTION 'account:resend_wait'; END IF;
 RETURN target_email;
END $function$

functions.admin_account_balances:
CREATE OR REPLACE FUNCTION public.admin_account_balances()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin'::public.app_role) THEN
  RAISE EXCEPTION 'account_balances:not_authorized' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',account.id,'username',account.username,'balance',account.balance::text,
   'lastTransactionDate',account.last_date) ORDER BY account.balance DESC,account.id),'[]'::jsonb)
 INTO result FROM (
   SELECT p.id,p.username,coalesce(sum(t.amount),0) balance,max(t.date) last_date
   FROM public.profiles p JOIN auth.users a ON a.id=p.id
   LEFT JOIN public.player_transactions t ON t.profile_id=p.id
   WHERE p.is_active GROUP BY p.id,p.username
 ) account;
 RETURN result;
END;
$function$
